-- Колода «Продвинутый C1» в общей базе слов. Напечатано vocabulario/deck2sql.py
-- Источник: vocabulario/baralho-completo-C1.json, карточек: 990.
-- Повторное выполнение безопасно: содержимое обновляется, прогресс людей не трогается.

begin;

values ('c1', 'Продвинутый C1', '990 карточек уровня C1: книжный регистр, право, обороты, разговорное', 'C1', 'C1', 50)
on conflict (id) do update set name = excluded.name, descr = excluded.descr,
  level_from = excluded.level_from, level_to = excluded.level_to, sort = excluded.sort;

on conflict (id) do update set deck_id = excluded.deck_id, word = excluded.word,
  pos = excluded.pos, ru = excluded.ru, ex = excluded.ex, exru = excluded.exru,
  note = excluded.note, level = excluded.level, tema = excluded.tema, sort = excluded.sort,
  uk = excluded.uk, exuk = excluded.exuk, noteuk = excluded.noteuk,
  en = excluded.en, exen = excluded.exen, noteen = excluded.noteen;

