insert into public.pt_decks (id, name, descr, level_from, level_to, sort)
insert into public.pt_words (id, deck_id, word, pos, ru, ex, exru, note, level, tema, sort, uk, exuk, noteuk, en, exen, noteen) values
('w:âmago','c1','o âmago','сущ.','сердцевина, глубинная суть','O âmago da questão não é o dinheiro, é a confiança.','Суть вопроса не в деньгах, а в доверии.','Книжное; в разговоре чаще «o fundo da questão»','C1','A1',0,'осердя, глибинна суть','Суть питання не в грошах, а в довірі.','Книжне; у розмові частіше «o fundo da questão»','the core, the innermost part','The core of the question isn''t money, it''s trust.','Bookish; in speech people say o fundo da questão'),
('w:índole','c1','a índole','сущ.','нрав, склад характера','É um rapaz de boa índole, incapaz de fazer mal.','Он парень доброго нрава, не способный причинить зло.','Также о явлении: crime de índole racista','C1','B1',1,'вдача, натура','Він хлопець доброї вдачі, не здатний чинити зло.','Також про явище: crime de índole racista','nature, disposition','He''s a boy of good nature, incapable of doing harm.','Also of a phenomenon: crime de índole racista'),
('w:vertente','c1','a vertente','сущ.','аспект, сторона вопроса','Convém analisar a vertente económica antes de tomar a decisão.','Стоит разобрать экономическую сторону, прежде чем принимать решение.','Прямое значение — склон горы','C1','A1',2,'аспект, бік питання','Варто розібрати економічний бік, перш ніж ухвалювати рішення.','Пряме значення — схил гори','aspect, side of an issue','The economic side should be examined before the decision is made.','The literal sense is a mountain slope'),
('w:teor','c1','o teor','сущ.','содержание сказанного или написанного','Não gostei do teor da carta que ele nos enviou.','Мне не понравилось содержание письма, которое он нам отправил.','Также доля вещества: teor de álcool','C1','A8',3,'зміст сказаного чи написаного','Мені не сподобався зміст листа, який він нам надіслав.','Також частка речовини: teor de álcool','the tenor of what is said or written','I didn''t like the tenor of the letter he sent us.','Also the proportion of a substance: teor de álcool'),
('w:envergadura','c1','a envergadura','сущ.','масштаб, размах','Trata-se de uma obra de grande envergadura e custo elevado.','Речь идёт о работе большого масштаба и высокой стоимости.','','C1','A3',4,'розмах, велич задуму','Ідеться про роботу великого масштабу і високої вартості.','','scale, magnitude','It is a work of great magnitude and high cost.',''),
('w:desígnio','c1','o desígnio','сущ.','замысел, предначертание','Ninguém conhecia o verdadeiro desígnio daquela viagem.','Никто не знал истинного замысла той поездки.','Книжное; в быту — intenção','C1','A1',5,'задум, накреслення','Ніхто не знав справжнього задуму тієї подорожі.','Книжне; у побуті — intenção','design, grand intention','Nobody knew the true purpose of that journey.','Bookish; in everyday speech, intenção'),
('w:intuito','c1','o intuito','сущ.','намерение, с каким что-то делается','Fez a pergunta com o intuito de nos ajudar.','Он задал вопрос с намерением нам помочь.','Почти всегда в обороте «com o intuito de»','C1','A1',6,'намір, з яким щось роблять','Він поставив запитання з наміром нам допомогти.','Майже завжди у звороті «com o intuito de»','the aim in doing something','He asked the question with the aim of helping us.','Almost always in the phrase com o intuito de'),
('w:proveniência','c1','a proveniência','сущ.','происхождение, откуда взялось','O museu não sabe a proveniência daquelas moedas antigas.','Музей не знает происхождения тех старинных монет.','','C1','A1',7,'походження, звідки взялося','Музей не знає походження тих старовинних монет.','','provenance, where something came from','The museum doesn''t know the provenance of those old coins.',''),
('w:génese','c1','a génese','сущ.','зарождение, истоки','A génese do conflito remonta ao século passado.','Истоки конфликта восходят к прошлому веку.','Женский род: a génese','C1','A1',8,'зародження, витоки','Витоки конфлікту сягають минулого століття.','Жіночий рід: a génese','genesis, origins','The origins of the conflict go back to the last century.','Feminine: a génese'),
('w:advento','c1','o advento','сущ.','наступление новой эпохи','Com o advento da internet, tudo mudou muito depressa.','С приходом интернета всё изменилось очень быстро.','','C1','A4',9,'настання нової доби','З приходом інтернету все змінилося дуже швидко.','','the advent of a new age','With the advent of the internet everything changed very fast.',''),
('w:surgimento','c1','o surgimento','сущ.','появление, возникновение','O surgimento de novas empresas trouxe emprego à região.','Появление новых компаний принесло работу в регион.','','C1','A1',10,'поява, виникнення','Поява нових компаній принесла роботу в регіон.','','the emergence','The emergence of new firms brought jobs to the region.',''),
('w:decadência','c1','a decadência','сущ.','упадок','O bairro entrou em decadência depois de fechar a fábrica.','Район пришёл в упадок после закрытия фабрики.','','C1','A1',11,'занепад','Квартал занепав після закриття фабрики.','','decline, decay','The district went into decline after the factory closed.',''),
('w:declínio','c1','o declínio','сущ.','спад, снижение','As vendas estão em declínio desde o início do ano.','Продажи снижаются с начала года.','«em declínio» — устойчивое сочетание','C1','A1',12,'спад, зниження','Продажі знижуються від початку року.','«em declínio» — стале сполучення','downturn','Sales have declined since the start of the year.','em declínio is the set phrase'),
('w:auge','c1','o auge','сущ.','разгар, высшая точка','A cidade está no auge da época turística.','Город на пике туристического сезона.','','C1','A4',13,'розпал, найвища точка','Місто в розпалі туристичного сезону.','','peak, height','The city is at the height of the tourist season.',''),
('w:ascensão','c1','a ascensão','сущ.','восхождение, стремительный подъём','A sua ascensão na empresa foi rápida e discreta.','Его подъём в компании был быстрым и незаметным.','','C1','A1',14,'сходження, стрімкий підйом','Його сходження в компанії було швидке і непомітне.','','rise, ascent','His rise in the company was quick and quiet.',''),
('w:subsistência','c1','a subsistência','сущ.','пропитание, средства к жизни','A pesca garante a subsistência de muitas famílias aqui.','Рыболовство обеспечивает пропитание многих семей здесь.','','C1','A1',15,'прожиток','Рибальство забезпечує прожиток багатьох родин тут.','','subsistence, a living','Fishing provides a living for many families here.',''),
('w:coexistência','c1','a coexistência','сущ.','сосуществование','A coexistência das duas línguas na ilha é pacífica.','Сосуществование двух языков на острове мирное.','','C1','A1',16,'співіснування','Співіснування двох мов на острові мирне.','','coexistence','The coexistence of the two languages on the island is peaceful.',''),
('w:interdependência','c1','a interdependência','сущ.','взаимозависимость','Há uma forte interdependência entre os dois setores.','Между двумя отраслями сильная взаимозависимость.','','C1','A9',17,'взаємозалежність','Між двома галузями сильна взаємозалежність.','','interdependence','There is a strong interdependence between the two sectors.',''),
('w:nexo','c1','o nexo','сущ.','логическая связь между явлениями','Não vejo nexo nenhum entre as duas histórias.','Я не вижу никакой связи между двумя историями.','«sem nexo» — бессвязный, бессмысленный','C1','A9',18,'логічний зв’язок','Я не бачу жодного зв’язку між двома історіями.','«sem nexo» — беззмістовний, без ладу','a logical link','I see no link at all between the two stories.','sem nexo — incoherent, making no sense'),
('w:correlação','c1','a correlação','сущ.','соотношение, корреляция','Existe correlação entre o sono e o rendimento escolar.','Есть корреляция между сном и школьной успеваемостью.','','C1','A9',19,'кореляція','Є кореляція між сном і шкільною успішністю.','','correlation','There is a correlation between sleep and school performance.',''),
('w:desfecho','c1','o desfecho','сущ.','развязка, исход дела','O desfecho do processo apanhou toda a gente de surpresa.','Исход дела застал всех врасплох.','','C1','A4',20,'розв’язка, вислід справи','Вислід справи заскочив усіх зненацька.','','outcome, denouement','The outcome of the case took everyone by surprise.',''),
('w:repercussão','c1','a repercussão','сущ.','отклик, отзвук в обществе','A notícia teve grande repercussão na imprensa nacional.','Новость получила большой отклик в национальной прессе.','','C1','A1',21,'відлуння в суспільстві','Новина мала великий відгук у національній пресі.','','repercussion, wide response','The story had a great impact in the national press.',''),
('w:trajetória','c1','a trajetória','сущ.','жизненный путь, послужной путь','A trajetória dela como investigadora impressiona qualquer júri.','Её путь как исследователя впечатляет любую комиссию.','','C1','A4',22,'життєвий і фаховий шлях','Її шлях як дослідниці вражає будь-яку комісію.','','the course of a career or life','Her record as a researcher impresses any panel.',''),
('w:retrocesso','c1','o retrocesso','сущ.','откат назад, шаг назад','Fechar a linha seria um retrocesso para toda a região.','Закрытие ветки стало бы шагом назад для всего региона.','','C1','A1',23,'відкат назад','Закриття гілки стало б кроком назад для всього регіону.','','a step backwards','Closing the line would be a step backwards for the whole region.',''),
('w:estagnação','c1','a estagnação','сущ.','застой','A economia vive uma estagnação que já dura anos.','Экономика переживает застой, который длится уже годы.','','C1','A1',24,'застій','Економіка переживає застій, що триває вже роками.','','stagnation','The economy is in a stagnation that has lasted years.',''),
('w:abrandamento','c1','o abrandamento','сущ.','замедление','Houve um abrandamento do consumo nos últimos meses.','В последние месяцы произошло замедление потребления.','Глагол abrandar — сбавлять скорость','C1','A1',25,'уповільнення','Останніми місяцями сталося уповільнення споживання.','Дієслово abrandar — стишувати швидкість','slowdown','There has been a slowdown in consumption in recent months.','The verb abrandar means to slow down'),
('w:rutura','c1','a rutura','сущ.','разрыв','A rutura entre os sócios deixou a empresa parada.','Разрыв между партнёрами остановил компанию.','Пишется rutura: ruptura — дореформенное написание','C1','A1',26,'розрив зв’язків','Розрив між партнерами спинив компанію.','Пишеться rutura: ruptura — дореформене написання','rupture, breakdown','The break between the partners left the company idle.','Spelt rutura: ruptura is the pre-reform spelling'),
('w:colapso','c1','o colapso','сущ.','крах, коллапс','O sistema informático esteve à beira do colapso.','Информационная система была на грани коллапса.','','C1','A1',27,'крах, колапс','Інформаційна система була на межі колапсу.','','collapse of a system','The computer system was on the verge of collapse.',''),
('w:derrocada','c1','a derrocada','сущ.','обвал, крушение','A derrocada do muro deixou a estrada cortada.','Обвал стены перекрыл дорогу.','И буквально, и переносно — о крахе','C1','A1',28,'обвал, завалення','Обвал муру перекрив дорогу.','І буквально, і переносно — про крах','the collapse of a structure; downfall','The wall collapsed and blocked the road.','Both literally and figuratively, of a downfall'),
('w:resiliência','c1','a resiliência','сущ.','жизнестойкость, умение держать удар','A resiliência desta gente perante a crise é notável.','Жизнестойкость этих людей перед лицом кризиса замечательна.','','C1','A6',29,'життєстійкість','Життєстійкість цих людей перед лицем кризи прикметна.','','resilience','These people''s resilience in the face of the crisis is remarkable.',''),
('w:fragilidade','c1','a fragilidade','сущ.','хрупкость, уязвимость','A fragilidade do acordo ficou clara logo na primeira semana.','Хрупкость соглашения стала ясна уже на первой неделе.','','C1','A6',30,'крихкість, вразливість','Крихкість угоди стала ясна вже першого тижня.','','fragility','The fragility of the agreement was clear in the first week.',''),
('w:contingência','c1','a contingência','сущ.','непредвиденное обстоятельство','O plano prevê várias contingências e atrasos possíveis.','План предусматривает разные непредвиденные обстоятельства и возможные задержки.','','C1','A1',31,'непередбачена обставина','План передбачає різні непередбачені обставини і можливі затримки.','','contingency','The plan allows for various contingencies and possible delays.',''),
('w:conjuntura','c1','a conjuntura','сущ.','текущее положение дел, конъюнктура','A atual conjuntura não convida a grandes investimentos.','Нынешняя обстановка не располагает к крупным вложениям.','','C1','A1',32,'поточне становище справ','Нинішня обстановка не спонукає до великих вкладень.','','the current state of affairs','The present climate does not invite big investments.',''),
('w:vigência','c1','a vigência','сущ.','срок действия документа','O contrato tem uma vigência de dois anos apenas.','Договор действует всего два года.','«em vigor» — действующий, в силе','C1','A4',33,'строк дії документа','Договір діє лише два роки.','«em vigor» — чинний, у силі','period of validity','The contract runs for only two years.','em vigor — in force, currently applying'),
('w:vigor','c1','o vigor','сущ.','сила, бодрость','Aos oitenta anos, mantém o vigor de um jovem.','В восемьдесят лет он сохраняет бодрость молодого.','«entrar em vigor» — вступать в силу','C1','A6',34,'снага, бадьорість','У вісімдесят років він зберігає снагу молодого.','«entrar em vigor» — набирати чинності','vigour','At eighty he keeps the vigour of a young man.','entrar em vigor — to come into force'),
('w:preponderância','c1','a preponderância','сущ.','преобладание, перевес','A preponderância do turismo mudou a cara da cidade.','Преобладание туризма изменило облик города.','','C1','A5',35,'переважання','Переважання туризму змінило обличчя міста.','','predominance','The predominance of tourism changed the face of the city.',''),
('w:prevalência','c1','a prevalência','сущ.','распространённость болезни','A prevalência da doença é maior no interior do país.','Распространённость болезни выше во внутренних районах страны.','Статистический и медицинский термин','C1','B6',36,'поширеність хвороби','Поширеність хвороби вища у внутрішніх районах країни.','Статистичний і медичний термін','prevalence of a disease','The prevalence of the disease is higher inland.','A statistical and medical term'),
('w:carência','c1','a carência','сущ.','нехватка, дефицит','Há carência de médicos nas zonas mais isoladas.','В самых отдалённых зонах не хватает врачей.','','C1','A5',37,'дефіцит, потреба в чомусь','У найвіддаленіших зонах бракує лікарів.','','want, unmet need','There is a shortage of doctors in the most isolated areas.',''),
('w:entrave','c1','o entrave','сущ.','помеха, тормоз для дела','A burocracia continua a ser o maior entrave ao investimento.','Бюрократия остаётся главной помехой для инвестиций.','','C1','A7',38,'перепона, гальмо для справи','Бюрократія лишається головною перепоною для інвестицій.','','obstacle, brake on progress','Bureaucracy is still the biggest obstacle to investment.',''),
('w:constrangimento','c1','o constrangimento','сущ.','неловкость, стеснение','Falou do assunto sem qualquer constrangimento à frente de todos.','Он говорил об этом без всякой неловкости при всех.','Во мн. ч. — ограничения: constrangimentos orçamentais','C1','A7',39,'ніяковість, скутість','Він говорив про це без жодної ніяковості при всіх.','У множині — обмеження: constrangimentos orçamentais','awkwardness; a constraint','He spoke about it without any awkwardness in front of everyone.','In the plural it means budgetary constraints'),
('w:salvaguarda','c1','a salvaguarda','сущ.','защитная оговорка, гарантия','O contrato inclui uma salvaguarda para casos de doença.','Договор включает оговорку на случай болезни.','','C1','B9',40,'застережна умова, гарантія','Договір містить застереження на випадок хвороби.','','safeguard','The contract includes a safeguard for cases of illness.',''),
('w:envolvente','c1','a envolvente','сущ.','окружающее пространство','A casa é modesta, mas a envolvente é magnífica.','Дом скромный, но местность вокруг великолепна.','','C1','A2',41,'довколишній простір','Дім скромний, але місцевість навколо чудова.','','the surroundings','The house is modest, but the setting is magnificent.',''),
('w:perímetro','c1','o perímetro','сущ.','периметр','A polícia isolou todo o perímetro do edifício.','Полиция оцепила весь периметр здания.','','C1','A3',42,'периметр','Поліція оточила весь периметр будівлі.','','perimeter','The police cordoned off the whole perimeter of the building.',''),
('w:encosta','c1','a encosta','сущ.','склон холма','As vinhas sobem pela encosta até ao cimo.','Виноградники поднимаются по склону до самого верха.','','C1','A2',43,'схил пагорба','Виноградники піднімаються схилом аж до верху.','','hillside','The vines climb the hillside to the very top.',''),
('w:sopé','c1','o sopé','сущ.','подножие горы','A aldeia fica no sopé da serra, junto ao rio.','Деревня стоит у подножия горы, рядом с рекой.','','C1','A2',44,'підніжжя гори','Село стоїть біля підніжжя гори, поруч із річкою.','','the foot of a mountain','The village lies at the foot of the hills, by the river.',''),
('w:foz','c1','a foz','сущ.','устье реки','A foz do Douro é um bom sítio para passear.','Устье Дору — хорошее место для прогулки.','Женский род: a foz','C1','A2',45,'гирло річки','Гирло Дору — гарне місце для прогулянки.','Жіночий рід: a foz','river mouth','The mouth of the Douro is a good place for a walk.','Feminine: a foz'),
('w:caudal','c1','o caudal','сущ.','водоток, объём воды в реке','O caudal do rio baixou muito durante o verão.','Уровень воды в реке сильно упал за лето.','','C1','A2',46,'водотік, обсяг води в річці','Рівень води в річці дуже впав за літо.','','the flow of a river','The river''s flow dropped a lot over the summer.',''),
('w:cais','c1','o cais','сущ.','причал, набережная','Ficámos no cais a ver os barcos a chegar.','Мы стояли на причале и смотрели, как приходят лодки.','Не меняется во мн. ч.: o cais, os cais','C1','A2',47,'причал, набережна','Ми стояли на причалі й дивилися, як приходять човни.','Не змінюється у множині: o cais, os cais','quay, wharf','We stood on the quay watching the boats come in.','Invariable in the plural: o cais, os cais'),
('w:enseada','c1','a enseada','сущ.','бухта','Encontrámos uma enseada calma para tomar banho.','Мы нашли спокойную бухту, чтобы искупаться.','','C1','A2',48,'бухта','Ми знайшли спокійну бухту, щоб скупатися.','','cove, inlet','We found a calm cove for a swim.',''),
